<?php require __DIR__.'/app/bootstrap.php';$songSlug=trim($_GET['song']??'');$site=setting('site_name','JattBeat');if($songSlug){$q=db()->prepare('SELECT s.*,a.name artist FROM songs s LEFT JOIN artists a ON a.id=s.artist_id WHERE s.slug=? AND s.published=1');$q->execute([$songSlug]);$s=$q->fetch();if(!$s){http_response_code(404);exit('Song not found');}$title=$s['meta_title']?:$s['title'].' – '.($s['artist']??$site);$desc=$s['meta_description']?:mb_substr(strip_tags($s['description']),0,155);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e(rtrim(APP_URL,'/').'/song/'.$s['slug'])?>"><meta property="og:type" content="music.song"><meta property="og:title" content="<?=e($title)?>"><meta property="og:description" content="<?=e($desc)?>"><?php if($s['artwork_url']):?><meta property="og:image" content="<?=e($s['artwork_url'])?>"><?php endif?><script type="application/ld+json"><?=json_encode(['@context'=>'https://schema.org','@type'=>'MusicRecording','name'=>$s['title'],'byArtist'=>$s['artist']?['@type'=>'MusicGroup','name'=>$s['artist']]:null,'image'=>$s['artwork_url']?:null,'datePublished'=>$s['release_date']?:null],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><link rel="stylesheet" href="/assets/style.css"></head><body><header class="top"><a class="brand" href="/"><?=e($site)?></a></header><main class="wrap"><?php if($s['artwork_url']):?><img class="cover" src="<?=e($s['artwork_url'])?>" alt="<?=e($s['title'])?>"><?php endif?><p class="eyebrow">MUSIC TRACK</p><h1><?=e($s['title'])?></h1><p><?=e($s['artist']??'Unknown artist')?> · <?=e($s['album'])?></p><p><?=nl2br(e($s['description']))?></p><?php if($s['media_url']):?><p><a class="button" href="<?=e($s['media_url'])?>" target="_blank" rel="nofollow noopener"><?= $s['media_type']==='download'?'Open authorized download':'Listen at authorized provider'?></a></p><?php endif?><p class="muted">Use only links you are authorized to share.</p></main></body></html><?php exit;}
$songs=db()->query("SELECT s.*,a.name artist FROM songs s LEFT JOIN artists a ON a.id=s.artist_id WHERE s.published=1 ORDER BY s.created_at DESC LIMIT 60")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($site)?> – Punjabi Music</title><meta name="description" content="<?=e(setting('site_description','Discover music and artists'))?>"><link rel="canonical" href="<?=e(APP_URL?:'/')?>"><link rel="stylesheet" href="/assets/style.css"></head><body><header class="top"><a class="brand" href="/"><?=e($site)?></a><nav><a href="/">Home</a><a href="/sitemap.xml">Sitemap</a><a href="/login.php">Admin</a></nav></header><main class="wrap"><section class="hero"><p class="eyebrow">MUSIC DISCOVERY</p><h1>Find your next favourite track.</h1><p>Explore published songs and artists.</p></section><h2>Latest music</h2><div class="grid"><?php foreach($songs as $s):?><article class="tile"><?php if($s['artwork_url']):?><img src="<?=e($s['artwork_url'])?>" alt="<?=e($s['title'])?>" loading="lazy"><?php else:?><div class="placeholder">♫</div><?php endif?><div class="tilebody"><h3><a href="/song/<?=e($s['slug'])?>"><?=e($s['title'])?></a></h3><p><?=e($s['artist']??'Unknown artist')?></p></div></article><?php endforeach?><?php if(!$songs):?><p>No published songs yet. Sign in to the admin panel to add music.</p><?php endif?></div></main><footer>© <?=date('Y')?> <?=e($site)?></footer></body></html>